// reverse returns s with its characters in reverse order.
// It works on runes so the result keeps the same character count
// and stays valid UTF-8 for strings with multi-byte characters.
func reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

// Reverse is the exported form of reverse.
func Reverse(s string) string {
	return reverse(s)
}

