	}
}

func TestReverse(t *testing.T) {
	cases := []struct {
		input string
		want  string
	}{
		{"hello", "olleh"},
		{"", ""},
		{"a", "a"},
		{"racecar", "racecar"},
		{"héllo", "olléh"},
	}
	for _, tc := range cases {
		got := reverse(tc.input)
		if got != tc.want {
			t.Errorf("reverse(%q) = %q, want %q", tc.input, got, tc.want)
		}
		if len([]rune(got)) != len([]rune(tc.input)) {
			t.Errorf("reverse(%q) changed length: got %d, want %d", tc.input, len([]rune(got)), len([]rune(tc.input)))
		}
	}
}

